memleak.exampleBefore:
void process() {
  char* buffer = new char[1024];
  // process data
  // Forgotten delete[] buffer;
}

memleak.exampleAfter:
void process() {
  std::unique_ptr<char[]> buffer(new char[1024]);
  // Memory is automatically freed when buffer goes out of scope
}

uninitvar.exampleBefore:
int x;
if (condition) { x = 5; }
std::cout << x; // Undefined behavior if condition is false

uninitvar.exampleAfter:
int x = 0; // Safe default
if (condition) { x = 5; }
std::cout << x;

outOfBounds.exampleBefore:
int arr[5];
for (int i = 0; i <= 5; ++i) { // Bug: <= 5 instead of < 5
  arr[i] = 0;
}

outOfBounds.exampleAfter:
int arr[5];
for (int i = 0; i < 5; ++i) {
  arr[i] = 0;
}
// Better: use std::array and range-based for loops

useClosedFile.exampleBefore:
FILE* f = fopen("data.txt", "r");
fclose(f);
char c = fgetc(f); // Error: f is already closed

useClosedFile.exampleAfter:
FILE* f = fopen("data.txt", "r");
if (f) {
  char c = fgetc(f);
  fclose(f);
}

resourceLeak.exampleBefore:
void readData() {
  FILE* f = fopen("data.txt", "r");
  if (error_condition) return; // f is leaked here
  fclose(f);
}

resourceLeak.exampleAfter:
void readData() {
  std::ifstream f("data.txt");
  if (error_condition) return; // f is safely closed by destructor
}
